{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Levodopa, a highly transferable analogue (assay-transfer score 0.9911), has an absolute oral bioavailability of 80.4% in healthy volunteers after fasting, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Metoclopramide, with assay-transfer score 0.9893, has a mean absolute bioavailability of 0.801 ± 0.049 versus IV in six subjects, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Meperidine, with assay-transfer score 0.9892, has an absolute oral bioavailability of 47–73% versus IV in healthy young men, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Bumetanide, with assay-transfer score 0.989, has an absolute bioavailability of 0.75 ± 0.11 in young subjects, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Phenylbutyrate, with assay-transfer score 0.9882, has an oral bioavailability of 78% in patients, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Lemborexant, with assay-transfer score 0.9882, has at least 87% oral bioavailability in healthy subjects, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues report absolute or systemic oral bioavailability values well above the 20% threshold, with no contradictory evidence. The query's favorable physicochemical properties are consistent with these observations, supporting a high oral bioavailability prediction.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule itself.",
    "First-pass metabolism and transporter-mediated clearance of the carbamate/aniline/benzylamine scaffold are not directly characterized.",
    "Solubility and dissolution behavior are inferred from physicochemical properties rather than measured experimentally."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

